from abc import ABC, abstractmethod

class State(ABC):
    @abstractmethod
    def insert_money(self, machine, amount): ...
    @abstractmethod
    def select_item(self, machine, code): ...
    @abstractmethod
    def dispense(self, machine): ...

class VendingMachine:
    def __init__(self, inventory):
        self.inventory = inventory
        self.balance = 0
        self.state = IdleState()          # 当前状态对象

    def set_state(self, state):
        self.state = state                # 唯一切换入口

    # 事件全部委托给当前状态
    def insert_money(self, amt): self.state.insert_money(self, amt)
    def select_item(self, code): self.state.select_item(self, code)
    def dispense(self):         self.state.dispense(self)

class IdleState(State):
    def insert_money(self, machine, amount):
        machine.balance += amount
        machine.set_state(HasMoneyState())     # 投币后转移

    def select_item(self, machine, code):
        raise InvalidAction("请先投币")          # 该状态下非法

    def dispense(self, machine):
        raise InvalidAction("尚未选择商品")
